-- Repair the order_items identity sequence after data imports/restores.
-- The table's primary key is generated by this sequence; a stale sequence
-- causes inserts to fail with duplicate key value ... order_items_pkey.
DO $$
DECLARE
  v_max_id bigint;
BEGIN
  SELECT max(id) INTO v_max_id FROM pos.order_items;

  IF v_max_id IS NULL THEN
    PERFORM setval('pos.order_items_id_seq'::regclass, 1, false);
  ELSE
    PERFORM setval('pos.order_items_id_seq'::regclass, v_max_id, true);
  END IF;
END
$$;
